namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;

    public RecipeService()
    {
        _categories = new List<RecipeCategory>
        {
            new() { Name = "Breakfast", Description = "Start your morning right", Icon = "🥞" },
            new() { Name = "Lunch", Description = "Midday meals and sandwiches", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Hearty evening dishes", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats and baked goods", Icon = "🍰" },
            new() { Name = "Snacks", Description = "Quick bites between meals", Icon = "🍿" },
            new() { Name = "Drinks", Description = "Smoothies, cocktails, and more", Icon = "🥤" }
        };

        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Pancakes", Category = "Breakfast", Ingredients = "2 cups flour\n2 eggs\n1 cup milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt", Steps = "1. Mix dry ingredients together\n2. Whisk eggs and milk separately\n3. Combine wet and dry ingredients\n4. Cook on a hot griddle until bubbles form\n5. Flip and cook until golden brown", AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Caesar Salad", Category = "Lunch", Ingredients = "1 head romaine lettuce\n1/2 cup croutons\n1/4 cup parmesan cheese\nCaesar dressing\nGrilled chicken (optional)", Steps = "1. Wash and chop romaine lettuce\n2. Toss with Caesar dressing\n3. Top with croutons and shaved parmesan\n4. Add grilled chicken if desired", AverageRating = 4.2, RatingCount = 8 },
            new() { Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner", Ingredients = "400g spaghetti\n500g ground beef\n1 can crushed tomatoes\n1 onion, diced\n3 cloves garlic\nOlive oil\nItalian herbs\nSalt and pepper", Steps = "1. Cook spaghetti according to package\n2. Sauté onion and garlic in olive oil\n3. Brown the ground beef\n4. Add crushed tomatoes and herbs\n5. Simmer for 20 minutes\n6. Serve sauce over spaghetti", AverageRating = 4.8, RatingCount = 25 },
            new() { Id = 4, Title = "Chocolate Chip Cookies", Category = "Desserts", Ingredients = "2 1/4 cups flour\n1 cup butter, softened\n3/4 cup sugar\n3/4 cup brown sugar\n2 eggs\n1 tsp vanilla\n1 tsp baking soda\n2 cups chocolate chips", Steps = "1. Cream butter and sugars together\n2. Beat in eggs and vanilla\n3. Mix in flour and baking soda\n4. Fold in chocolate chips\n5. Drop spoonfuls onto baking sheet\n6. Bake at 375°F for 9-11 minutes", AverageRating = 4.9, RatingCount = 30 },
            new() { Id = 5, Title = "Guacamole", Category = "Snacks", Ingredients = "3 ripe avocados\n1 lime, juiced\n1 tsp salt\n1/2 cup onion, diced\n3 tbsp fresh cilantro\n2 roma tomatoes, diced\n1 tsp garlic, minced\n1 pinch cayenne pepper", Steps = "1. Cut avocados in half and remove pit\n2. Mash avocado in a bowl\n3. Stir in lime juice and salt\n4. Mix in onion, cilantro, tomatoes, and garlic\n5. Add cayenne pepper\n6. Serve with tortilla chips", AverageRating = 4.6, RatingCount = 18 },
            new() { Id = 6, Title = "Berry Smoothie", Category = "Drinks", Ingredients = "1 cup mixed berries\n1 banana\n1 cup yogurt\n1/2 cup milk\n1 tbsp honey", Steps = "1. Add all ingredients to blender\n2. Blend until smooth\n3. Pour into glass and serve immediately", AverageRating = 4.3, RatingCount = 10 }
        };
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public List<Recipe> GetAllRecipes() => _recipes;

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            var totalRating = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = (totalRating + stars) / recipe.RatingCount;
        }
    }
}

