@page "/recipes/{CategoryName}"
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>
<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

@if (Recipes.Any())
{
    <div class="row">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">
                            <span class="text-warning">@GetStarDisplay(recipe.AverageRating)</span>
                            <small class="text-muted">(@recipe.RatingCount ratings)</small>
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <div class="alert alert-info">No recipes found in this category yet. <a href="/submit">Submit one!</a></div>
}

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> Recipes { get; set; } = new();

    protected override void OnParametersSet()
    {
        var category = RecipeService.GetCategories()
            .FirstOrDefault(c => c.Name.Equals(CategoryName, StringComparison.OrdinalIgnoreCase));

        if (category is not null)
        {
            CategoryName = category.Name;
            Recipes = RecipeService.GetRecipesByCategory(CategoryName);
        }
    }

    private string GetStarDisplay(double rating)
    {
        var fullStars = (int)Math.Round(rating);
        return new string('★', fullStars) + new string('☆', 5 - fullStars);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (Recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/recipes/@Recipe.Category.ToLower()">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        </ol>
    </nav>

    <h1>@Recipe.Title</h1>

    <StarRating RecipeId="Recipe.Id" CurrentRating="Recipe.AverageRating" RatingCount="Recipe.RatingCount" />

    <div class="row mt-4">
        <div class="col-md-5">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">🧾 Ingredients</h5></div>
                <div class="card-body">
                    <ul class="list-unstyled mb-0">
                        @foreach (var ingredient in Recipe.Ingredients.Split('\n'))
                        {
                            <li class="mb-1">• @ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-7">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">📝 Steps</h5></div>
                <div class="card-body">
                    @foreach (var step in Recipe.Steps.Split('\n'))
                    {
                        <p class="mb-2">@step</p>
                    }
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

@using Microsoft.AspNetCore.Components.Web
@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="my-3">
    <span class="me-2">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= HoverRating ? "star-hover" : (star <= SelectedRating ? "star-selected" : ""))"
              style="font-size: 1.5rem; cursor: pointer;"
              @onmouseover="() => HoverRating = star"
              @onmouseout="() => HoverRating = 0"
              @onclick="() => SubmitRating(star)">
            @(star <= (HoverRating > 0 ? HoverRating : SelectedRating) ? "★" : "☆")
        </span>
    }
    <span class="ms-3 text-muted">
        @CurrentRating.ToString("F1") avg (@RatingCount ratings)
    </span>
    @if (Submitted)
    {
        <span class="ms-2 text-success">✓ Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int HoverRating { get; set; }
    private int SelectedRating { get; set; }
    private bool Submitted { get; set; }

    private void SubmitRating(int stars)
    {
        SelectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        Submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

<div class="row">
    <div class="col-md-8">
        <EditForm Model="NewRecipe" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
            <DataAnnotationsValidator />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="NewRecipe.Title" placeholder="e.g., Grandma's Apple Pie" />
                <ValidationMessage For="() => NewRecipe.Title" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="NewRecipe.Category">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat.Name">@cat.Icon @cat.Name</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => NewRecipe.Category" />
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="NewRecipe.Ingredients" placeholder="One ingredient per line" />
                <ValidationMessage For="() => NewRecipe.Ingredients" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="NewRecipe.Steps" placeholder="One step per line" />
                <ValidationMessage For="() => NewRecipe.Steps" />
            </div>

            <button type="submit" class="btn btn-success" disabled="@IsSubmitting">
                @if (IsSubmitting)
                {
                    <span>Submitting...</span>
                }
                else
                {
                    <span>🚀 Submit Recipe</span>
                }
            </button>
        </EditForm>

        @if (SubmitSuccess)
        {
            <div class="alert alert-success mt-3">
                ✅ Recipe submitted successfully! <a href="/recipe/@SubmittedId">View it here</a>.
            </div>
        }
    </div>
</div>

@code {
    private Recipe NewRecipe { get; set; } = new();
    private bool IsSubmitting { get; set; }
    private bool SubmitSuccess { get; set; }
    private int SubmittedId { get; set; }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(NewRecipe.Title) ||
            string.IsNullOrWhiteSpace(NewRecipe.Category) ||
            string.IsNullOrWhiteSpace(NewRecipe.Ingredients) ||
            string.IsNullOrWhiteSpace(NewRecipe.Steps))
        {
            return;
        }

        IsSubmitting = true;
        RecipeService.AddRecipe(NewRecipe);
        SubmittedId = NewRecipe.Id;
        SubmitSuccess = true;
        IsSubmitting = false;
        NewRecipe = new Recipe();
    }
}

