@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

<div class="row">
    <div class="col-md-8">
        <EditForm Model="NewRecipe" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
            <DataAnnotationsValidator />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="NewRecipe.Title" placeholder="e.g., Grandma's Apple Pie" />
                <ValidationMessage For="() => NewRecipe.Title" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="NewRecipe.Category">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat.Name">@cat.Icon @cat.Name</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => NewRecipe.Category" />
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="NewRecipe.Ingredients" placeholder="One ingredient per line" />
                <ValidationMessage For="() => NewRecipe.Ingredients" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="NewRecipe.Steps" placeholder="One step per line" />
                <ValidationMessage For="() => NewRecipe.Steps" />
            </div>

            <button type="submit" class="btn btn-success" disabled="@IsSubmitting">
                @if (IsSubmitting)
                {
                    <span>Submitting...</span>
                }
                else
                {
                    <span>🚀 Submit Recipe</span>
                }
            </button>
        </EditForm>

        @if (SubmitSuccess)
        {
            <div class="alert alert-success mt-3">
                ✅ Recipe submitted successfully! <a href="/recipe/@SubmittedId">View it here</a>.
            </div>
        }
    </div>
</div>

@code {
    private Recipe NewRecipe { get; set; } = new();
    private bool IsSubmitting { get; set; }
    private bool SubmitSuccess { get; set; }
    private int SubmittedId { get; set; }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(NewRecipe.Title) ||
            string.IsNullOrWhiteSpace(NewRecipe.Category) ||
            string.IsNullOrWhiteSpace(NewRecipe.Ingredients) ||
            string.IsNullOrWhiteSpace(NewRecipe.Steps))
        {
            return;
        }

        IsSubmitting = true;
        RecipeService.AddRecipe(NewRecipe);
        SubmittedId = NewRecipe.Id;
        SubmitSuccess = true;
        IsSubmitting = false;
        NewRecipe = new Recipe();
    }
}

